sealed class EngineException(message: String): kotlin.Exception(message) {
        
        class Network(message: String) : EngineException(message)
        
        class UnsupportedUrl(message: String) : EngineException(message)
        
        class StreamNotFound(message: String) : EngineException(message)
        
        class FfmpegException(message: String) : EngineException(message)
        
        class FfmpegNotFound(message: String) : EngineException(message)
        
        class TaggingException(message: String) : EngineException(message)
        
        class IoException(message: String) : EngineException(message)
        
        class Serialization(message: String) : EngineException(message)
        
        class InvalidConfig(message: String) : EngineException(message)
        
        class Cancelled(message: String) : EngineException(message)
        
        class QuicFallbackExhausted(message: String) : EngineException(message)
        
        class Torrent(message: String) : EngineException(message)
        
        class ExtractorException(message: String) : EngineException(message)
        
        class ConcurrencyException(message: String) : EngineException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<EngineException> {
        override fun lift(error_buf: RustBuffer.ByValue): EngineException = FfiConverterTypeEngineError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeEngineError : FfiConverterRustBuffer<EngineException> {
    override fun read(buf: ByteBuffer): EngineException {
        
            return when(buf.getInt()) {
            1 -> EngineException.Network(FfiConverterString.read(buf))
            2 -> EngineException.UnsupportedUrl(FfiConverterString.read(buf))
            3 -> EngineException.StreamNotFound(FfiConverterString.read(buf))
            4 -> EngineException.FfmpegException(FfiConverterString.read(buf))
            5 -> EngineException.FfmpegNotFound(FfiConverterString.read(buf))
            6 -> EngineException.TaggingException(FfiConverterString.read(buf))
            7 -> EngineException.IoException(FfiConverterString.read(buf))
            8 -> EngineException.Serialization(FfiConverterString.read(buf))
            9 -> EngineException.InvalidConfig(FfiConverterString.read(buf))
            10 -> EngineException.Cancelled(FfiConverterString.read(buf))
            11 -> EngineException.QuicFallbackExhausted(FfiConverterString.read(buf))
            12 -> EngineException.Torrent(FfiConverterString.read(buf))
            13 -> EngineException.ExtractorException(FfiConverterString.read(buf))
            14 -> EngineException.ConcurrencyException(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: EngineException): ULong {
        return 4UL
    }

    override fun write(value: EngineException, buf: ByteBuffer) {
        when(value) {
            is EngineException.Network -> {
                buf.putInt(1)
                Unit
            }
            is EngineException.UnsupportedUrl -> {
                buf.putInt(2)
                Unit
            }
            is EngineException.StreamNotFound -> {
                buf.putInt(3)
                Unit
            }
            is EngineException.FfmpegException -> {
                buf.putInt(4)
                Unit
            }
            is EngineException.FfmpegNotFound -> {
                buf.putInt(5)
                Unit
            }
            is EngineException.TaggingException -> {
                buf.putInt(6)
                Unit
            }
            is EngineException.IoException -> {
                buf.putInt(7)
                Unit
            }
            is EngineException.Serialization -> {
                buf.putInt(8)
                Unit
            }
            is EngineException.InvalidConfig -> {
                buf.putInt(9)
                Unit
            }
            is EngineException.Cancelled -> {
                buf.putInt(10)
                Unit
            }
            is EngineException.QuicFallbackExhausted -> {
                buf.putInt(11)
                Unit
            }
            is EngineException.Torrent -> {
                buf.putInt(12)
                Unit
            }
            is EngineException.ExtractorException -> {
                buf.putInt(13)
                Unit
            }
            is EngineException.ConcurrencyException -> {
                buf.putInt(14)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





